export const INITIAL_TIMETABLE: TimetableSlot[] = RAW_INITIAL_TIMETABLE.filter((slot) => {
  const sec = slot.section || 'أ';
  return INITIAL_STUDENTS.some(
    (s) => s.gradeLevel === slot.gradeLevel && (s.section === sec || (!s.section && sec === 'أ'))
  );
});

